package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

/** Analytic and typed-host fixtures. Separate Electron integration supplies real rendered evidence. */
public class ObservationArtifact128Test {
 static JSONObject definition(){return new JSONObject().put("profile128",ObservationArtifact128.KIND).put("request","Create an observation-to-artifact explorer").put("title","Motion control").put("modelName","Java observation procedure").put("runId",UUID.randomUUID()).put("geometryId",UUID.randomUUID()).put("horizonS",.6).put("maxGapS",.6).put("accelerationBoundMps2",2).put("saveSkillName","motion-control");}
 static JSONObject analytic(){var rows=new JSONArray();for(int i=0;i<8;i++)rows.put(new JSONObject().put("ordinal",i+1).put("seconds",i*.1).put("accepted",true).put("status","measured-estimate").put("positionM",new JSONArray(new double[]{2*i*.1,3-i*.1})).put("radiusM",.01));return new JSONObject().put("rows",rows);}
 @Test public void causalLinearMotionHasKnownVelocityErrorAndUncertainty(){var src=analytic();var f=ObservationArtifact128.forecast(src,definition());assertEquals(6,f.getJSONObject("metrics").getInt("compared"));assertEquals(0,f.getJSONObject("metrics").getDouble("maxErrorM"),1e-12);var p=f.getJSONArray("rows").getJSONObject(2).getJSONObject("forecast");assertEquals(.4,p.getJSONArray("positionM").getDouble(0),1e-12);assertEquals(.04,p.getDouble("radiusM"),1e-12);assertEquals(2.6,f.getJSONObject("future").getJSONArray("positionM").getDouble(0),1e-12);assertFalse(f.getJSONArray("rows").getJSONObject(1).getJSONObject("forecast").getBoolean("available"));}
 @Test public void rejectedPointsNeverTrainVelocityAndLongGapsWithhold(){var src=analytic();src.getJSONArray("rows").getJSONObject(3).put("accepted",false).put("status","prediction-only").put("positionM",new JSONArray("[999,999]"));var f=ObservationArtifact128.forecast(src,definition());var p=f.getJSONArray("rows").getJSONObject(4).getJSONObject("forecast");assertEquals(.8,p.getJSONArray("positionM").getDouble(0),1e-12);assertEquals("[2,3]",p.getJSONArray("fromOrdinals").toString());src.getJSONArray("rows").getJSONObject(7).put("seconds",2);assertFalse(ObservationArtifact128.forecast(src,definition()).getJSONArray("rows").getJSONObject(7).getJSONObject("forecast").getBoolean("available"));}
 @Test public void irregularTimesAndFutureDataDoNotLeakIntoEarlierForecast(){var src=analytic();src.getJSONArray("rows").getJSONObject(5).put("positionM",new JSONArray("[8,4]"));var f=ObservationArtifact128.forecast(src,definition());assertEquals(1,f.getJSONArray("rows").getJSONObject(5).getJSONObject("forecast").getJSONArray("positionM").getDouble(0),1e-12);assertTrue(f.getJSONObject("metrics").getDouble("maxErrorM")>7);assertTrue(f.getJSONObject("metrics").getInt("covered")<f.getJSONObject("metrics").getInt("compared"));src.getJSONArray("rows").getJSONObject(5).put("seconds",.1);assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.forecast(src,definition()));}
 @Test public void numericAndExecutableInputBoundsRefuseBeforeMutation(){assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("horizonS",3)));assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("maxGapS",".5")));assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("handler","shell")));var s=analytic();for(Object raw:s.getJSONArray("rows"))((JSONObject)raw).put("accepted",false);assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.forecast(s,definition()));}
 static final class Fixture implements AutoCloseable {
  final WorkflowTest.Fixture f;final WorldObservationStore obs;final MetricObservationStore metric;final ObservationArtifact128 service;final Path root;
  Fixture(Path root)throws Exception{this.root=root;f=new WorkflowTest.Fixture(root);obs=new WorldObservationStore(root,f.goals.worlds());metric=new MetricObservationStore(root,obs,f.goals.worlds());service=new ObservationArtifact128(obs,metric,f.goals.worlds());f.workflows.install128(service);}
  JSONObject input()throws Exception{var world=f.goals.worlds().create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"128 labelled fixture");var d=WorldObservationStoreTest.importPack(obs,WorldObservationStoreTest.pack());var times=new JSONArray();for(int i=0;i<9;i++)times.put(i*.1);metric.clock(new JSONObject().put("datasetId",d.getString("id")).put("seconds",times).put("source","Labelled synthetic test clock").put("cameraKey","test-fixed"));var run=WorldObservationStoreTest.settled(obs,obs.start(WorldObservationStoreTest.arguments(f.goals.worlds(),world.getString("id"),d,0)).getString("id"));assertEquals("completed",run.getString("status"));var g=metric.geometry(PlaneCalibrationTest.mat().put("imagePoints",new JSONArray("[[0,0],[1,0],[1,1],[0,1]]")));return definition().put("runId",run.getString("id")).put("geometryId",g.getString("id"));}
  public void close()throws Exception{obs.close();f.close();}
 }
 static JSONObject fixtureHost(JSONObject artifact){
  var d=new JSONObject(artifact.getJSONObject("contents").getString("observation.json"));var src=d.getJSONObject("forecast").getJSONArray("rows");var cells=new JSONArray();
  for(Object raw:src){var r=(JSONObject)raw;var p=r.getJSONObject("forecast");var cell=new JSONArray().put(""+r.getInt("ordinal")).put(""+r.getDouble("seconds")).put(r.getString("status"));for(JSONObject v:List.of(r,p)){cell.put(v.has("positionM")?""+v.getJSONArray("positionM").getDouble(0):"—").put(v.has("positionM")?""+v.getJSONArray("positionM").getDouble(1):"—").put(v.has("radiusM")?""+v.getDouble("radiusM"):"—");}cells.put(cell);}
  var frames=new JSONArray();int[] indexes={0,src.length()-1,src.length()/2,src.length()-1},axes={0,0,1,1};
  for(int k=0;k<4;k++){int axis=axes[k],index=indexes[k];var values=new ArrayList<Double>();for(Object raw:src){var r=(JSONObject)raw;if(r.getBoolean("accepted")&&r.has("positionM"))values.add(r.getJSONArray("positionM").getDouble(axis));var p=r.getJSONObject("forecast");if(p.getBoolean("available"))values.add(p.getJSONArray("positionM").getDouble(axis));}double min=Collections.min(values),max=Collections.max(values),t0=src.getJSONObject(0).getDouble("seconds"),t1=src.getJSONObject(src.length()-1).getDouble("seconds");var points=new JSONArray();for(String series:List.of("measured","forecast"))for(int i=0;i<=index;i++){var r=src.getJSONObject(i);var p=series.equals("measured")?r:r.getJSONObject("forecast");if(!(series.equals("measured")?r.getBoolean("accepted"):p.getBoolean("available"))||!p.has("positionM"))continue;points.put(new JSONObject().put("series",series).put("ordinal",r.getInt("ordinal")).put("visible",true).put("x",(double)(float)(60+780*(r.getDouble("seconds")-t0)/(t1-t0))).put("y",(double)(float)(280-240*(p.getJSONArray("positionM").getDouble(axis)-min)/Math.max(1e-9,max-min))));}var r=src.getJSONObject(index);frames.put(new JSONObject().put("axis",axis).put("index",index).put("visible",true).put("selection","Frame "+r.getInt("ordinal")+" / "+String.format(Locale.ROOT,"%.6f",r.getDouble("seconds"))+" s / "+r.getString("status")).put("points",points));}
  var m=d.getJSONObject("forecast").getJSONObject("metrics");var summary=new JSONArray().put(""+m.getInt("measured")).put(""+m.getInt("compared")).put(String.format(Locale.ROOT,"%.6f",m.getDouble("meanErrorM"))).put(""+m.getInt("rejected"));var f=d.getJSONObject("forecast").getJSONObject("future");String future=f.getBoolean("available")?String.format(Locale.ROOT,"Bounded future at %.6f s: X %.6f m; Y %.6f m; radius %.6f m. Conditional forecast, not an observation.",f.getDouble("seconds"),f.getJSONArray("positionM").getDouble(0),f.getJSONArray("positionM").getDouble(1),f.getDouble("radiusM")):"Future withheld: "+f.getString("reason");var source=d.getJSONObject("source");String sourceText="World "+source.getJSONObject("nativeBinding").getString("worldId")+" / body "+source.getString("bodyId")+" / run "+source.getString("runId")+". "+source.getString("source")+" · "+source.getString("license");
  return new JSONObject().put("id",artifact.getString("id")).put("version",artifact.getInt("version")).put("rows",cells).put("frames",frames).put("summary",summary).put("future",future).put("source",sourceText);
 }
 static JSONObject complete(Fixture x,JSONObject input)throws Exception{var w=x.f.workflows.start(input);var c=WorkflowTest.driveToAudit(x.f,w.getString("id"));assertEquals(0,x.f.goals.procedures().length());var a=x.f.artifacts.read(c.getJSONObject("report").getString("id"));WorkflowTest.workflowAck(x.f,c,fixtureHost(a));var done=WorkflowTest.completed(x.f,w.getString("id"));assertEquals(done.toString(),"completed",done.getString("status"));return done;}
 @Test public void realTrackerToTypedHostFixturePreservesSourceAndSavesOnlyAfterAudit()throws Exception{try(var x=new Fixture(Files.createTempDirectory("observation128"))){var in=x.input();var original=x.obs.read(in.getString("runId"));var done=complete(x,in);assertTrue(original.similar(x.obs.read(in.getString("runId"))));assertEquals(1,x.f.goals.activeProcedures127().length());assertTrue(x.f.workflows.inspectProcedure127(new JSONObject().put("id",done.getJSONObject("savedSkill").getString("id"))).getJSONObject("evidence").getBoolean("passed"));assertTrue(x.f.workflows.verifyArchive110(done.getString("id")).getBoolean("passed"));}}
 @Test public void originalImageTamperRefusesAdmissionWithoutReservation()throws Exception{try(var x=new Fixture(Files.createTempDirectory("observation128-image"))){var in=x.input();var run=x.obs.read(in.getString("runId"));var image=x.root.resolve("world-observations/datasets/"+run.getString("datasetId")+"/3.image");Files.write(image,new byte[]{1,2,3});assertThrows(IllegalStateException.class,()->x.f.workflows.start(in));assertFalse(x.f.goals.workflowReserved());assertEquals(0,x.f.workflows.list().length());}}
 @Test public void changedCalibrationAndBodyRefuseFreshMission()throws Exception{try(var x=new Fixture(Files.createTempDirectory("observation128-camera"))){var in=x.input();var wrong=x.metric.geometry(PlaneCalibrationTest.mat().put("cameraKey","moved-camera"));assertThrows(IllegalStateException.class,()->x.f.workflows.start(WorldFrames.copy(in).put("geometryId",wrong.getString("id"))));assertThrows(IllegalArgumentException.class,()->x.f.workflows.start(WorldFrames.copy(in).put("bodyId","other")));}}
 @Test public void coldRestartContinuesSameForecastAndRejectsStaleClaim()throws Exception{var root=Files.createTempDirectory("observation128-restart");JSONObject saved,input;try(var x=new Fixture(root)){input=x.input().put("reviewAfterForecast128",true);saved=x.f.workflows.start(input);saved=WorkflowTest.completed(x.f,saved.getString("id"));assertEquals("interrupted",saved.getString("status"));assertEquals("artifact",saved.getString("step"));assertEquals(0,x.f.goals.procedures().length());}try(var x=new Fixture(root)){var resumed=x.f.workflows.resume(saved.getString("id"));assertTrue(saved.getJSONObject("forecast128").similar(resumed.getJSONObject("forecast128")));var c=WorkflowTest.driveToAudit(x.f,saved.getString("id"));assertThrows(IllegalStateException.class,()->WorkflowTest.workflowAck(x.f,WorldFrames.copy(c).put("nonce","wrong"),fixtureHost(x.f.artifacts.read(c.getJSONObject("report").getString("id")))));WorkflowTest.workflowAck(x.f,c,fixtureHost(x.f.artifacts.read(c.getJSONObject("report").getString("id"))));assertEquals("completed",WorkflowTest.completed(x.f,saved.getString("id")).getString("status"));}}
 @Test public void independentHiddenOrAlteredRenderedOutputCannotComplete()throws Exception{try(var x=new Fixture(Files.createTempDirectory("observation128-false"))){var w=x.f.workflows.start(x.input());var c=WorkflowTest.driveToAudit(x.f,w.getString("id"));var actual=fixtureHost(x.f.artifacts.read(c.getJSONObject("report").getString("id")));actual.getJSONArray("rows").getJSONArray(0).put(3,"999");actual.getJSONArray("frames").getJSONObject(1).getJSONArray("points").getJSONObject(0).put("visible",false);var result=WorkflowTest.workflowAck(x.f,c,actual);assertEquals("interrupted",result.getString("status"));assertEquals(0,x.f.goals.procedures().length());assertFalse(result.getJSONArray("auditHistory").getJSONObject(0).getBoolean("passed"));}}
 @Test public void lifecycleReuseFreshSourceAndReportTamperKeepOriginalEvidence()throws Exception{try(var x=new Fixture(Files.createTempDirectory("observation128-reuse"))){var done=complete(x,x.input());var skill=done.getJSONObject("savedSkill");var fresh=x.input();var reuse=new JSONObject().put("name",skill.getString("name")).put("version",skill.getInt("version")).put("runId",fresh.getString("runId")).put("geometryId",fresh.getString("geometryId"));var w=x.f.workflows.reuse(reuse);var c=WorkflowTest.driveToAudit(x.f,w.getString("id"));WorkflowTest.workflowAck(x.f,c,fixtureHost(x.f.artifacts.read(c.getJSONObject("report").getString("id"))));assertEquals("completed",WorkflowTest.completed(x.f,w.getString("id")).getString("status"));assertNotEquals(done.getJSONObject("sourceBinding128").getString("runId"),w.getJSONObject("sourceBinding128").getString("runId"));ProcedureLifecycle127Test.change(x.f,skill,"retire");assertThrows(IllegalStateException.class,()->x.f.workflows.reuse(reuse));ProcedureLifecycle127Test.passed(ProcedureLifecycle127Test.change(x.f,skill,"reactivate"));var a=x.f.artifacts.read(done.getJSONObject("report").getString("id"));x.f.artifacts.write(new JSONObject().put("id",a.getString("id")).put("expectedVersion",1).put("title","Changed report").put("files",new JSONObject().put("index.html","<body>Changed</body>")));assertFalse(x.f.workflows.inspectProcedure127(new JSONObject().put("id",skill.getString("id"))).getJSONObject("evidence").getBoolean("passed"));assertThrows(IllegalStateException.class,()->x.f.workflows.reuse(reuse));}}
}
